import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.Boholvbs.js";const m=JSON.parse('{"title":"CLI reference","description":"Every prioricode command, subcommand, flag, and default — TUI, run, serve, web, attach, acp, providers, mcp, agent, plugin, upgrade, uninstall, models, stats, export, import, session, db, github, pr.","frontmatter":{"title":"CLI reference","description":"Every prioricode command, subcommand, flag, and default — TUI, run, serve, web, attach, acp, providers, mcp, agent, plugin, upgrade, uninstall, models, stats, export, import, session, db, github, pr."},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}'),c={name:"reference/cli.md"};function a(i,e,s,n,l,h){return d(),o("div",null,[...e[0]||(e[0]=[r('<p>Global behavior first, then commands alphabetically-ish (grouped by intent). Flags marked <em>(hidden)</em> exist in source but don&#39;t appear in <code>--help</code>. Everything after <code>--</code> on any command is passthrough.</p><h2 id="global-flags" tabindex="-1">Global flags <a class="header-anchor" href="#global-flags" aria-label="Permalink to &quot;Global flags&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Effect</th></tr></thead><tbody><tr><td><code>-h, --help</code></td><td>Help (logo-prefixed, hand-rolled renderer)</td></tr><tr><td><code>-v, --version</code></td><td>Print the installed version</td></tr><tr><td><code>--print-logs</code></td><td>Mirror logs to stderr (= <code>PRIORICODE_PRINT_LOGS=1</code>)</td></tr><tr><td><code>--log-level DEBUG|INFO|WARN|ERROR</code></td><td>Log verbosity (= <code>PRIORICODE_LOG_LEVEL</code>)</td></tr><tr><td><code>--pure</code></td><td>Run without external plugins (= <code>PRIORICODE_PURE=1</code>)</td></tr><tr><td><code>prioricode completion</code></td><td>Print a shell completion script</td></tr></tbody></table><p>Every run also exports <code>AGENT=1</code>, <code>PRIORICODE=1</code>, <code>PRIORICODE_PID</code> into its process environment — child scripts can detect they&#39;re agent-spawned.</p><h2 id="prioricode-project-—-the-tui" tabindex="-1"><code>prioricode [project]</code> — the TUI <a class="header-anchor" href="#prioricode-project-—-the-tui" aria-label="Permalink to &quot;`prioricode [project]` — the TUI&quot;">​</a></h2><p><code>prioricode [project-path]</code> · start interactive sessions.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>positional <code>project</code></td><td><code>$PWD</code></td><td>start in this directory</td></tr><tr><td><code>-m, --model &lt;provider/model&gt;</code></td><td>resolution order</td><td>see <a href="./../getting-started/providers.html">providers</a></td></tr><tr><td><code>-c, --continue</code></td><td>off</td><td>resume the most recent session</td></tr><tr><td><code>-s, --session &lt;id&gt;</code></td><td>—</td><td>resume a specific session</td></tr><tr><td><code>--fork</code></td><td>off</td><td>branch on resume (requires <code>-c</code> or <code>-s</code>)</td></tr><tr><td><code>--prompt &lt;text&gt;</code></td><td>—</td><td>first message; piped stdin is prepended</td></tr><tr><td><code>--agent &lt;name&gt;</code></td><td><code>default_agent</code>/<code>build</code></td><td>starting agent</td></tr><tr><td><code>--auto</code></td><td>off</td><td>auto-approve asks not explicitly denied (dangerous)</td></tr><tr><td><code>--yolo</code>, <code>--dangerously-skip-permissions</code> <em>(hidden)</em></td><td>off</td><td>aliases feeding <code>--auto</code></td></tr><tr><td><code>--mini</code></td><td>off</td><td>minimal interactive interface (split footer)</td></tr><tr><td><code>--no-replay</code>, <code>--replay-limit &lt;n&gt;</code> <em>(hidden)</em></td><td>—</td><td>require <code>--mini</code>; transcript rendering in mini</td></tr><tr><td><code>--demo</code> <em>(hidden)</em></td><td>off</td><td>require <code>--mini</code></td></tr><tr><td><code>--port</code>, <code>--hostname</code>, <code>--mdns</code>, <code>--mdns-domain</code>, <code>--cors</code></td><td><code>0</code>, <code>127.0.0.1</code>, off, <code>prioricode.local</code>, none</td><td>network options; also serve the instance&#39;s API (see <code>serve</code>)</td></tr></tbody></table><p>Incompatibilities: <code>--mini</code> refuses the network flags; replay knobs refuse a non-mini run.</p><h2 id="prioricode-run-message-—-headless" tabindex="-1"><code>prioricode run [message..]</code> — headless <a class="header-anchor" href="#prioricode-run-message-—-headless" aria-label="Permalink to &quot;`prioricode run [message..]` — headless&quot;">​</a></h2><p>Non-interactive by default: prompt → stream → exit on idle. (Full guide: <a href="./../using/headless.html">headless</a>.)</p><table tabindex="0"><thead><tr><th>Flag</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>message…</code> / <code>--</code> passthrough</td><td>empty</td><td>the prompt; piped stdin appended</td></tr><tr><td><code>--command &lt;name&gt;</code></td><td>—</td><td>run a registered slash command; message becomes its args</td></tr><tr><td><code>-c, --continue</code> / <code>-s, --session</code> / <code>--fork</code></td><td>—</td><td>as in TUI; <code>--fork</code> needs <code>-c</code>/<code>-s</code></td></tr><tr><td><code>-m, --model</code>, <code>--agent</code>, <code>--variant</code>, <code>--thinking</code></td><td>per config</td><td><code>--thinking</code> default: true only when interactive</td></tr><tr><td><code>--format default|json</code></td><td><code>default</code></td><td>JSONL events: <code>tool_use</code>, <code>step_start</code>, <code>step_finish</code>, <code>text</code>, <code>reasoning</code>, <code>error</code></td></tr><tr><td><code>-f, --file &lt;path&gt;</code> <em>(repeatable)</em></td><td>—</td><td>attach ≤10 MiB/file</td></tr><tr><td><code>--title &lt;t&gt;</code></td><td>auto</td><td>empty value ⇒ first 50 chars of prompt</td></tr><tr><td><code>--share</code></td><td>off</td><td>share the finished session</td></tr><tr><td><code>--attach &lt;url&gt;</code> + <code>-u/--username</code>, <code>-p/--password</code></td><td>—</td><td>drive a remote server (env defaults: <code>PRIORICODE_SERVER_USERNAME</code>=<code>prioricode</code>, <code>…_PASSWORD</code>)</td></tr><tr><td><code>--dir &lt;path&gt;</code></td><td>cwd</td><td>project directory</td></tr><tr><td><code>--port &lt;n&gt;</code></td><td>random</td><td>local server port when not attaching</td></tr><tr><td><code>--auto</code> (+ hidden <code>--yolo</code>, <code>--dangerously-skip-permissions</code>)</td><td>off</td><td>approve-all mode</td></tr><tr><td><code>--interactive, -i</code></td><td>off</td><td>declared; interactivity is derived from <code>--mini</code>, not this</td></tr><tr><td><code>--mini</code> <em>(hidden)</em></td><td>off</td><td>present but rejected — use <code>prioricode --mini</code></td></tr><tr><td><code>--replay</code>, <code>--replay-limit</code>, <code>--demo</code> <em>(hidden)</em></td><td>—</td><td>mini knobs</td></tr></tbody></table><h2 id="prioricode-serve-·-web-·-acp-·-attach" tabindex="-1"><code>prioricode serve</code> · <code>web</code> · <code>acp</code> · <code>attach</code> <a class="header-anchor" href="#prioricode-serve-·-web-·-acp-·-attach" aria-label="Permalink to &quot;`prioricode serve` · `web` · `acp` · `attach`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Shape</th></tr></thead><tbody><tr><td><code>serve</code></td><td>Headless server. Network flags only. Warns when <code>PRIORICODE_SERVER_PASSWORD</code> unset.</td></tr><tr><td><code>web</code></td><td>Server + opens the embedded app UI; prints local/mDNS URLs.</td></tr><tr><td><code>acp</code></td><td>Agent Client Protocol server over stdio. Network flags + <code>--cwd &lt;path&gt;</code>. Sets <code>PRIORICODE_CLIENT=acp</code>.</td></tr><tr><td><code>attach &lt;url&gt;</code></td><td>TUI against a remote server: <code>--dir</code>, <code>-c/-s/--fork</code>, <code>-u/-p</code>, <code>--mini</code>, replay knobs.</td></tr></tbody></table><h2 id="prioricode-providers-alias-auth" tabindex="-1"><code>prioricode providers</code> (alias <code>auth</code>) <a class="header-anchor" href="#prioricode-providers-alias-auth" aria-label="Permalink to &quot;`prioricode providers` (alias `auth`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sub</th><th>Flags</th><th>Notes</th></tr></thead><tbody><tr><td><code>list</code> (<code>ls</code>)</td><td>—</td><td>stored credentials (<code>&lt;data&gt;/auth.json</code>) + detected env-var providers</td></tr><tr><td><code>login [url]</code></td><td><code>-p/--provider &lt;id-or-name&gt;</code>, <code>-m/--method &lt;label&gt;</code></td><td><code>[url]</code> = well-known enterprise flow (<code>.well-known/prioricode</code>)</td></tr><tr><td><code>logout [provider]</code></td><td>—</td><td>forget one or all</td></tr></tbody></table><h2 id="prioricode-mcp" tabindex="-1"><code>prioricode mcp</code> <a class="header-anchor" href="#prioricode-mcp" aria-label="Permalink to &quot;`prioricode mcp`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sub</th><th>Flags</th><th>Notes</th></tr></thead><tbody><tr><td><code>list</code> (<code>ls</code>)</td><td>—</td><td>status per server: connected/disabled/needs_auth/needs_client_registration/failed</td></tr><tr><td><code>add [name]</code></td><td>non-interactive: <code>--url &lt;u&gt; [--header K=V]…</code> <strong>or</strong> <code>-- cmd args… [--env K=V]…</code></td><td>writes project or global config (comment-preserving)</td></tr><tr><td><code>auth [name]</code> / <code>auth list</code></td><td>—</td><td>OAuth flow / token inventory</td></tr><tr><td><code>logout [name]</code></td><td>—</td><td>forget tokens/clients</td></tr><tr><td><code>debug &lt;name&gt;</code></td><td>—</td><td>probe remote: discovery, registration, token state</td></tr></tbody></table><h2 id="prioricode-agent" tabindex="-1"><code>prioricode agent</code> <a class="header-anchor" href="#prioricode-agent" aria-label="Permalink to &quot;`prioricode agent`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sub</th><th>Flags</th><th>Notes</th></tr></thead><tbody><tr><td><code>create</code></td><td><code>--path</code>, <code>--description</code>, <code>--mode all|primary|subagent</code>, <code>--permissions &lt;csv&gt;</code> (alias <code>--tools</code>), <code>-m/--model</code></td><td>non-interactive iff all of path+description+mode+permissions given; writes <code>agents/&lt;name&gt;.md</code> under the target config dir</td></tr><tr><td><code>list</code></td><td>—</td><td><code>name (mode)</code> + permission JSON</td></tr></tbody></table><p>Permission keys selectable at create: <code>bash, read, edit, glob, grep, webfetch, task, todowrite, sessions, websearch, lsp, skill</code> — anything unselected is <strong>denied</strong>.</p><h2 id="prioricode-plugin-module-alias-plug" tabindex="-1"><code>prioricode plugin &lt;module&gt;</code> (alias <code>plug</code>) <a class="header-anchor" href="#prioricode-plugin-module-alias-plug" aria-label="Permalink to &quot;`prioricode plugin &lt;module&gt;` (alias `plug`)&quot;">​</a></h2><p><code>--global/-g</code>, <code>--force/-f</code>. Installs an npm plugin (or loads a local file) and registers it in config. Manifest expectations: <code>exports[&quot;./tui&quot;]</code>, <code>exports[&quot;./server&quot;]</code>, <code>package.json</code> main, or the legacy <code>prioricode-themes</code> list.</p><h2 id="prioricode-upgrade-target-uninstall" tabindex="-1"><code>prioricode upgrade [target]</code> / <code>uninstall</code> <a class="header-anchor" href="#prioricode-upgrade-target-uninstall" aria-label="Permalink to &quot;`prioricode upgrade [target]` / `uninstall`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Flags</th><th>Notes</th></tr></thead><tbody><tr><td><code>upgrade [target]</code></td><td><code>-m/--method curl|npm|pnpm|bun|brew|choco|scoop</code></td><td>target like <code>0.1.48</code>/<code>v0.1.48</code>; detects install method; verifies result</td></tr><tr><td><code>uninstall</code></td><td><code>-c/--keep-config</code>, <code>-d/--keep-data</code>, <code>--dry-run</code>, <code>-f/--force</code></td><td>removes dirs, PATH lines (<code># prioricode</code>), package via owning manager</td></tr></tbody></table><h2 id="catalog-data-commands" tabindex="-1">Catalog &amp; data commands <a class="header-anchor" href="#catalog-data-commands" aria-label="Permalink to &quot;Catalog &amp; data commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Flags</th><th>Notes</th></tr></thead><tbody><tr><td><code>models [provider]</code></td><td><code>--verbose</code>, <code>--refresh</code></td><td><code>provider/model</code> lines; <code>--refresh</code> re-fetches the catalog</td></tr><tr><td><code>stats</code></td><td><code>--days &lt;n&gt;</code> (<code>0</code>=today), <code>--tools</code>, <code>--models</code>, <code>--project &lt;p&gt;</code></td><td>cost/token aggregates; empty <code>--project</code> = current</td></tr><tr><td><code>export [sessionID]</code></td><td><code>--sanitize</code></td><td>JSON to stdout (picker if no id; status to stderr)</td></tr><tr><td><code>import &lt;file&gt;</code></td><td>—</td><td>local export or <code>https://&lt;host&gt;/share/&lt;slug&gt;</code></td></tr><tr><td><code>session list</code></td><td><code>-n/--max-count</code>, <code>--format table|json</code></td><td>paginated via bundled <code>less</code> (Windows fallbacks)</td></tr><tr><td><code>session delete &lt;id&gt;</code></td><td>—</td><td></td></tr><tr><td><code>db [query]</code></td><td><code>--format json|tsv</code> (default <code>tsv</code>)</td><td>sqlite3 shell or one-shot query</td></tr><tr><td><code>db path</code></td><td>—</td><td>print resolved DB file</td></tr></tbody></table><h2 id="github-commands" tabindex="-1">GitHub commands <a class="header-anchor" href="#github-commands" aria-label="Permalink to &quot;GitHub commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Flags</th><th>Notes</th></tr></thead><tbody><tr><td><code>github install</code></td><td>—</td><td>app + workflow + OIDC walkthrough</td></tr><tr><td><code>github run</code></td><td><code>--event &lt;file&gt;</code>, <code>--token &lt;pat&gt;</code></td><td>replay an event JSON locally</td></tr><tr><td><code>pr &lt;number&gt;</code></td><td>—</td><td>needs git repo + <code>gh</code>; checkout <code>pr/&lt;n&gt;</code>, import linked session, launch TUI</td></tr></tbody></table><h2 id="hidden-developer" tabindex="-1">Hidden &amp; developer <a class="header-anchor" href="#hidden-developer" aria-label="Permalink to &quot;Hidden &amp; developer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Notes</th></tr></thead><tbody><tr><td><code>console login/logout/switch/orgs/open</code></td><td>PrioriCode console account (device-code flow) — hidden from help (<a href="./../platforms/enterprise.html">enterprise</a>)</td></tr><tr><td><code>generate</code></td><td>dump OpenAPI + inject JS samples (SDK developer tooling)</td></tr><tr><td><code>debug …</code></td><td><code>info</code>, <code>paths</code>, <code>config</code>, <code>lsp</code>, <code>ripgrep</code>, <code>file</code>, <code>search</code>, <code>skill</code>, <code>snapshot</code>, <code>startup</code>, <code>agent</code>, <code>v2</code>, <code>wait</code> (<a href="./../support/troubleshooting.html">troubleshooting</a>)</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../using/headless.html">Headless</a> — <code>run</code> patterns for CI. <ul><li><a href="./environment-variables.html">Environment variables</a> — The env twins of these flags.</li><li><a href="./../platforms/server.html">Server</a> — What serve/web/attach/acp all speak.</li></ul></li></ul>',32)])])}const u=t(c,[["render",a]]);export{m as __pageData,u as default};
